using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows.Forms;

internal static class PresetParameterTests
{
    static void Check(bool value,string message){if(!value)throw new Exception(message);}
    static void Near(double a,double b,string message){Check(Math.Abs(a-b)<.002,message+": "+a+" / "+b);}
    static object Get(object target,string field){return target.GetType().GetField(field,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(target);}
    static void Set(object target,string field,object value){target.GetType().GetField(field,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(target,value);}
    static object Call(object target,string name,params object[] args){return target.GetType().GetMethods(BindingFlags.Instance|BindingFlags.NonPublic).First(m=>m.Name==name&&m.GetParameters().Length==args.Length).Invoke(target,args);}
    static void Mouse(Control target,string method,int x,int y){typeof(Control).GetMethod(method,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(target,new object[]{new MouseEventArgs(MouseButtons.Left,1,x,y,0)});}
    static Track CameraTrack(string name,int lane){return new Track{id="camera-"+lane,name=name,kind="camera",lane=lane,start=10,end=110,x=320,y=240,cameraZoom=1.1,angle=7};}
    static object Pose(Track t,int frame)
    {
        var p=Motion.At(t,frame);var c=t.kind=="camera"?Camera.At(t,frame,new RoomData()):new CameraPose();
        return new{x=p.x,y=p.y,angle=p.angle,zoom=Motion.Value(t,"cameraZoom",frame),blur=Motion.Value(t,"cameraBlur",frame),blurAngle=Motion.Value(t,"cameraBlurAngle",frame),intensity=Motion.Value(t,"cameraIntensity",frame),viewX=c.x,viewY=c.y,viewAngle=c.angle,viewZoom=c.zoom,viewBlur=c.blur,viewBlurAngle=c.blurAngle};
    }
    static void Samples(string file,string times,string target)
    {
        var s=Json.Read<EditorState>(File.ReadAllText(file));Motion.Normalize(s);var result=new Dictionary<string,object>();
        foreach(int f in times.Split(',').Select(Int32.Parse))result[f.ToString()]=s.tracks.ToDictionary(t=>t.id,t=>Pose(t,f));File.WriteAllText(target,Json.Write(result));
    }
    [STAThread] static int Main(string[] args)
    {
        try{
            if(args[0]=="--samples"){Samples(args[1],args[2],args[3]);return 0;}
            string folder=args[0];Directory.CreateDirectory(folder);Application.EnableVisualStyles();Language.Select(folder,"zh-CN");
            var legacy=typeof(CameraPresets).GetMethod("ApplyLegacy",BindingFlags.Static|BindingFlags.NonPublic);double largest=0;string largestName="",detail="";
            foreach(string name in CameraPresets.Names){
                var t=CameraTrack(name,0);legacy.Invoke(null,new object[]{t,name,10,50});var old=t.Snapshot();var scene=new EditorState{fps=50,duration=200,tracks=new List<Track>{t}};Motion.Normalize(scene);
                Check(CameraPresets.Bound(t),"Legacy preset did not migrate: "+name);Check(!t.keyframes.Any(k=>CameraPresets.ControlledFields.Contains(k.property)),"Legacy camera keys remain: "+name);
                for(int f=10;f<=110;f++){var a=Camera.At(old,f,new RoomData());var b=Camera.At(t,f,new RoomData());double delta=Math.Max(Math.Abs(a.x-b.x),Math.Max(Math.Abs(a.y-b.y),Math.Max(Math.Abs(a.angle-b.angle),Math.Max(Math.Abs(a.zoom-b.zoom),Math.Abs(a.blur-b.blur)))));if(delta>largest){largest=delta;largestName=name;detail="frame="+f+" x="+a.x+"/"+b.x+" zoom="+a.zoom+"/"+b.zoom+" angle="+a.angle+"/"+b.angle+" blur="+a.blur+"/"+b.blur;}}
                var edited=CameraTrack(name,0);legacy.Invoke(null,new object[]{edited,name,10,50});var key=edited.keyframes.First(k=>CameraPresets.ControlledFields.Contains(k.property));key.value+=3;int before=edited.keyframes.Count;Motion.Normalize(new EditorState{fps=50,duration=200,tracks=new List<Track>{edited}});Check(!CameraPresets.Bound(edited)&&edited.keyframes.Count==before,"Edited legacy camera was overwritten: "+name);
                if(StylePresets.Cameras.Contains(name)){var origin=CameraTrack(name,0);legacy.Invoke(null,new object[]{origin,name,10,50});origin.cameraOriginX+=40;Motion.Normalize(new EditorState{fps=50,duration=200,tracks=new List<Track>{origin}});Check(!CameraPresets.Bound(origin)&&origin.cameraOriginX!=origin.x,"Custom legacy camera origin was overwritten: "+name);}
            }
            Console.WriteLine("Legacy unedited camera maximum channel difference: "+largest+" / "+largestName+" / "+detail);
            foreach(int length in new[]{51,81,99,101,151,201,241,500})foreach(string name in CameraPresets.Names){var t=CameraTrack(name,0);t.end=t.start+length;legacy.Invoke(null,new object[]{t,name,10,50});var old=t.Snapshot();Motion.Normalize(new EditorState{fps=50,duration=1000,tracks=new List<Track>{t}});Check(CameraPresets.Bound(t),"Legacy preset duration failed to migrate: "+name+" / "+length);for(int f=t.start;f<=t.end;f++){var a=Camera.At(old,f,new RoomData());var b=Camera.At(t,f,new RoomData());double delta=Math.Max(Math.Abs(a.x-b.x),Math.Max(Math.Abs(a.y-b.y),Math.Max(Math.Abs(a.angle-b.angle),Math.Max(Math.Abs(a.zoom-b.zoom),Math.Abs(a.blur-b.blur)))));if(delta>largest){largest=delta;largestName=name+" / "+length;}}}
            Console.WriteLine("Legacy sampled durations maximum channel difference: "+largest+" / "+largestName);
            Check(largest<.000001,"Legacy camera migration changed its existing motion: "+largest+" / "+largestName+" / "+detail);
            foreach(string name in new[]{"甩镜过渡","横向甩镜过渡","轻微手持"}){var t=CameraTrack(name,0);t.end=511;legacy.Invoke(null,new object[]{t,name,10,50});Motion.Normalize(new EditorState{fps=50,duration=600,tracks=new List<Track>{t}});var copy=TrackPreset.Capture(name,new[]{t},50).Instantiate(200,100).Single();for(int f=0;f<=1002;f++){var a=CameraPresets.Sample(t.cameraPreset,10+f/2.0,50);var b=CameraPresets.Sample(copy.cameraPreset,200+f,100);Near(a.x,b.x,"Legacy copy/FPS X "+name+"/"+f);Near(a.y,b.y,"Legacy copy/FPS Y "+name+"/"+f);Near(a.angle,b.angle,"Legacy copy/FPS angle "+name+"/"+f);Near(a.zoom,b.zoom,"Legacy copy/FPS zoom "+name+"/"+f);Near(a.blur,b.blur,"Legacy copy/FPS blur "+name+"/"+f);}}
            var fixture=new EditorState{name="Preset verification",fps=50,duration=600,room="rAvoidance",tracks=new List<Track>()};int lane=0;
            foreach(string name in MotionPresets.Names){var t=new Track{id="motion-"+lane,name=name,kind="object",lane=lane++,start=10,end=110,x=310,y=210,sprite="sprBullet"};MotionPresets.Apply(t,name,10);t.motionPreset.turns=1.37;t.motionPreset.phase=21;t.motionPreset.end=103;MotionPresets.Bake(t);Motion.SetKey(t,"alpha",60,.4);fixture.tracks.Add(t);}
            foreach(string name in CameraPresets.Names){var t=CameraTrack(name,lane++);CameraPresets.Apply(t,name,10,50);t.cameraPreset.speed=1.13;t.cameraPreset.amplitudeX*=1.21;t.cameraPreset.amplitudeY*=.86;t.cameraPreset.angleAmplitude*=1.31;t.cameraPreset.zoomAmplitude*=.83;t.cameraPreset.blurAmplitude*=.72;t.cameraPreset.end=103;CameraPresets.Refresh(t);Motion.SetKey(t,"cameraIntensity",10,.65);Motion.SetKey(t,"cameraIntensity",90,.8);fixture.tracks.Add(t);}
            foreach(string name in new[]{"甩镜过渡","横向甩镜过渡","轻微手持"}){var t=CameraTrack(name,lane++);t.end=251;legacy.Invoke(null,new object[]{t,name,10,50});Motion.Normalize(new EditorState{fps=50,duration=400,tracks=new List<Track>{t}});Check(t.cameraPreset.legacySampling,"Legacy curve mode absent: "+name);t.cameraPreset.amplitudeX*=1.2;t.cameraPreset.zoomAmplitude*=.8;if(name=="轻微手持")t.cameraPreset.speed=.83;CameraPresets.Refresh(t);fixture.tracks.Add(t);}
            foreach(var original in fixture.tracks.Where(t=>CameraPresets.Bound(t)&&t.cameraPreset.legacySampling&&t.name!="轻微手持").ToArray()){var copy=TrackPreset.Capture("scaled legacy",new[]{original},50).Instantiate(10,100).Single();copy.lane=lane++;fixture.tracks.Add(copy);}
            {var original=fixture.tracks.First(t=>CameraPresets.Bound(t)&&t.cameraPreset.legacySampling);CameraPresets.Sample(original.cameraPreset,30,50);var cached=original.Snapshot();Check(Object.ReferenceEquals(original.cameraPreset.samples,cached.cameraPreset.samples),"Immutable legacy samples were rebuilt for every preview snapshot");CameraPresets.Translate(cached,25,0);Check(cached.cameraPreset.samples==null&&original.cameraPreset.samples!=null,"Editing a snapshot altered the original sample cache");}
            var combined=CameraTrack("combined",lane++);CameraPresets.Apply(combined,"柔和摇摆",10,50);MotionPresets.Apply(combined,"圆周运动",10);fixture.tracks.Add(combined);Motion.Normalize(fixture);
            foreach(var t in fixture.tracks)Check(!t.keyframes.Any(k=>MotionPresets.Generated(t,k.property)),"Preset created controlled keys: "+t.id);
            var restored=Json.Read<EditorState>(Json.Write(fixture));Motion.Normalize(restored);Check(SceneComparison.Same(fixture,restored),"Preset save/reopen lost parameters or time transforms");
            var camera=fixture.tracks.First(t=>CameraPresets.Bound(t));var snap=camera.Snapshot();snap.cameraPreset.centerX+=40;Check(camera.cameraPreset.centerX!=snap.cameraPreset.centerX,"Snapshot shares camera parameters");
            var imported=TrackPreset.Capture("camera",new[]{camera},50).Instantiate(200,100).Single();Check(imported.cameraPreset.start==200&&imported.cameraPreset.end==386&&!imported.keyframes.Any(k=>CameraPresets.Generated(imported,k.property)),"Preset copy/FPS did not preserve camera parameters");
            var move=camera.Snapshot();TimelineLayout.ShiftClock(move,30);Check(move.cameraPreset.start==camera.cameraPreset.start+30&&move.cameraPreset.end==camera.cameraPreset.end+30,"Moving camera lost its preset time");TimelineEditing.Resize(move,move.start,move.end,move.start,move.end+50,"sync");Check(move.cameraPreset.end==move.end&&!move.keyframes.Any(k=>CameraPresets.Generated(move,k.property)),"Resizing camera recreated keys");
            {var dragged=camera.Snapshot();var s=new EditorState{fps=50,duration=600,laneCount=1,tracks=new List<Track>{dragged}};dragged.lane=0;Motion.Normalize(s);using(var timeline=new TimelineCanvas{State=s,Size=new System.Drawing.Size(1400,350),PixelsPerSecond=250,ClipSnap=false,SelectionKeyframesOnly=true}){timeline.ReadModifiers=()=>Keys.None;timeline.CreateControl();timeline.SetTrackSelection(new[]{dragged},dragged);timeline.RefreshLayout();var bounds=timeline.ClipBounds(dragged);int x=(int)(bounds.X+bounds.Width/2),y=(int)bounds.Y+8,first=dragged.cameraPreset.start;Mouse(timeline,"OnMouseDown",x,y);Mouse(timeline,"OnMouseMove",x+50,y);Mouse(timeline,"OnMouseUp",x+50,y);Check(dragged.start==20&&dragged.cameraPreset.start==first+10,"Timeline dragging did not move camera preset clock");}}
            var stale=camera.Snapshot();stale.keyframeCycle=new KeyframeCycle{length=30,keys=new List<Keyframe>{new Keyframe{property="x",frame=2,value=1},new Keyframe{property="cameraIntensity",frame=2,value=.5}}};CameraPresets.Refresh(stale);Check(stale.keyframeCycle!=null&&stale.keyframeCycle.keys.Count==1&&stale.keyframeCycle.keys[0].property=="cameraIntensity","Preset cleanup lost independent cycle keys");TimelineEditing.Resize(stale,stale.start,stale.end,stale.start,stale.end+30,"sync");Check(!stale.keyframes.Any(k=>CameraPresets.Generated(stale,k.property)),"Resize restored stale preset sample keys");
            var selected=fixture.tracks.First(t=>MotionPresets.Bound(t));Check(CursorSnapping.Capture(new EditorState{fps=50,duration=250,tracks=new List<Track>{selected}},selected,0,true)(47)==null,"Preset controls added snap targets");
            using(var form=new MainForm(folder)){var s=new EditorState{fps=50,duration=250,tracks=new List<Track>{camera}};Motion.Normalize(s);var doc=new LoadData{state=s,room=new RoomData(),inventory=new Inventory{sprites=new[]{"sprBullet"},objects=new string[0],scripts=new string[0],rooms=new[]{"rAvoidance"},objectSprites=new Dictionary<string,string>()},waveform=new WaveData{duration=5,peaks=new double[30]}};Set(form,"state",s);Set(form,"document",doc);var timeline=(TimelineCanvas)Get(form,"timeline");timeline.State=s;Call(form,"SelectTrack",camera,null);var bag=(NativeProperties)((ParameterInspector)Get(form,"properties")).SelectedObject;Check(bag.GetProperties()["X"].IsReadOnly&&(string)bag.GetProperties()["X"].GetValue(bag)=="由预设控制","Camera controlled field label missing");Check(bag.GetProperties()["预设中心 X"]!=null&&bag.GetProperties()["预设速度倍率"]!=null&&bag.GetProperties()["拉镜预设持续时间 / 帧"]!=null,"Camera controls missing");double before=camera.cameraPreset.centerX;bag.GetProperties()["预设中心 X"].SetValue(bag,before+25);Near(camera.cameraPreset.centerX,before+25,"Camera center edit");Call(form,"AddAllKeys");Check(!camera.keyframes.Any(k=>CameraPresets.Generated(camera,k.property)),"Add all keys inserted controlled camera fields");Language.Select(folder,"en");Call(form,"ShowProperties");bag=(NativeProperties)((ParameterInspector)Get(form,"properties")).SelectedObject;Check((string)bag.GetProperties()["X"].GetValue(bag)=="Controlled by preset"&&Language.Text("预设速度倍率")=="Preset speed multiplier","Camera controlled labels lack English");Language.Select(folder,"zh-CN");var both=combined.Snapshot();MotionPresets.Apply(both,"水平往返",10);s.tracks.Add(both);Motion.Normalize(s);timeline.State=s;Call(form,"SelectTrack",both,null);bag=(NativeProperties)((ParameterInspector)Get(form,"properties")).SelectedObject;Check(bag.GetProperties()["水平振幅"]!=null&&bag.GetProperties()["拉镜水平振幅"]!=null,"Combined camera and motion controls conflict");}
            File.WriteAllText(Path.Combine(folder,"scene.json"),Json.Write(fixture));string times="0,10,11,20,35,50,60,70,90,102,103,110,129,130,131,132,150,240,250,251,274,275,276,277";Samples(Path.Combine(folder,"scene.json"),times,Path.Combine(folder,"expected.json"));
            Console.WriteLine("PASS: 14 motion and 12 camera presets, controlled fields, editable parameters, legacy migration/edited preservation, copy/FPS, resize, snapping and fixture export.");return 0;
        }catch(Exception error){Console.Error.WriteLine(error);return 1;}
    }
}
